	,(N'fbc1ec2e-5506-45bb-bedd-f2f6be3c9ecf', N'map.tblEmailTemplateToAlarmAndEvent', N'64B99EFE-9B71-4E01-AC04-1DED944FFA2B',	NULL,	N'2024-07-02 23:28:27.8052718 -04:00',	NULL, N'2024-07-02 23:28:27.8052718 -04:00', NULL,	1,	0,	NULL,	NULL	)

) AS SOURCE ([SyncTableGuid], [TableName], [SyncDependencyGroupGuid], [LastSchemaDate], [CreatedDate], [CreatedBy], [UpdatedDate], [UpdatedBy], [IsSiteFilteredFlag], [IsSiteFilteredOnDeleteFlag], [ParentSyncTableGuid], [ParentForeignKeyColumnName])
ON (Target.[SyncTableGuid] = Source.[SyncTableGuid])
WHEN MATCHED AND EXISTS (SELECT Target.[TableName]
						, Target.[SyncDependencyGroupGuid]
						, Target.[LastSchemaDate]
						, Target.[CreatedDate]
						, Target.[CreatedBy]
						, Target.[UpdatedDate]
						, Target.[UpdatedBy] 
						, Target.[IsSiteFilteredFlag]
						, Target.[IsSiteFilteredOnDeleteFlag]
						, Target.[ParentSyncTableGuid]
						, Target.[ParentForeignKeyColumnName]
						EXCEPT 
						SELECT Source.[TableName]
						, Source.[SyncDependencyGroupGuid]
						, Source.[LastSchemaDate]
						, Source.[CreatedDate]
						, Source.[CreatedBy]
						, Source.[UpdatedDate]
						, Source.[UpdatedBy]
						, Source.[IsSiteFilteredFlag] 
						, Source.[IsSiteFilteredOnDeleteFlag]
						, Source.[ParentSyncTableGuid]
						, Source.[ParentForeignKeyColumnName] ) THEN
	UPDATE SET [TableName] = Source.[TableName]
				, [SyncDependencyGroupGuid] = Source.[SyncDependencyGroupGuid]
				, [LastSchemaDate] = Source.[LastSchemaDate]
				, [CreatedDate] = Source.[CreatedDate]
				, [CreatedBy] =	Source.[CreatedBy]
				, [UpdatedDate] = Source.[UpdatedDate]
				, [UpdatedBy] =	Source.[UpdatedBy]
				, [IsSiteFilteredFlag] = Source.[IsSiteFilteredFlag]
				, [IsSiteFilteredOnDeleteFlag] = Source.[IsSiteFilteredOnDeleteFlag]
				, [ParentSyncTableGuid] = Source.[ParentSyncTableGuid]
				, [ParentForeignKeyColumnName] = Source.[ParentForeignKeyColumnName]
WHEN NOT MATCHED THEN
	INSERT ([SyncTableGuid], [TableName], [SyncDependencyGroupGuid], [LastSchemaDate], [CreatedDate], [CreatedBy], [UpdatedDate], [UpdatedBy], [IsSiteFilteredFlag], [IsSiteFilteredOnDeleteFlag], [ParentSyncTableGuid], [ParentForeignKeyColumnName])
		VALUES (Source.[SyncTableGuid], Source.[TableName], Source.[SyncDependencyGroupGuid], Source.[LastSchemaDate], Source.[CreatedDate], Source.[CreatedBy], Source.[UpdatedDate], Source.[UpdatedBy], Source.[IsSiteFilteredFlag], Source.[IsSiteFilteredOnDeleteFlag], Source.[ParentSyncTableGuid], Source.[ParentForeignKeyColumnName])
OUTPUT
   $action AS ActionType,
   deleted.[TableName],
   inserted.[TableName],
   deleted.[SyncDependencyGroupGuid],
   inserted.[SyncDependencyGroupGuid],
   deleted.[LastSchemaDate],
   inserted.[LastSchemaDate],
   deleted.[CreatedDate],
   inserted.[CreatedDate],
   deleted.[CreatedBy],
   inserted.[CreatedBy],
   deleted.[UpdatedDate],
   inserted.[UpdatedDate],
   deleted.[UpdatedBy],
   inserted.[UpdatedBy],
   deleted.[IsSiteFilteredFlag],
   inserted.[IsSiteFilteredFlag],
   deleted.[IsSiteFilteredOnDeleteFlag],
   inserted.[IsSiteFilteredOnDeleteFlag],
   deleted.[ParentSyncTableGuid],
   inserted.[ParentSyncTableGuid],
   deleted.[ParentForeignKeyColumnName],
   inserted.[ParentForeignKeyColumnName]
INTO @tblSyncTableRefData;

SELECT @SyncTableInserted = COUNT(*) FROM @tblSyncTableRefData WHERE ActionType IN ( 'INSERT' );
SELECT @SyncTableUpdated = COUNT(*) FROM @tblSyncTableRefData WHERE ActionType IN ( 'UPDATE' )
SELECT @SyncTableDeleted = COUNT(*) FROM @tblSyncTableRefData WHERE ActionType IN ( 'DELETE' )

IF (@SyncTableInserted > 0)
BEGIN
	PRINT '** ' + CONVERT(NVARCHAR(25), @SyncTableInserted) + ' NEW RECORDS INSERTED INTO [sync].[tblSyncTable] **'
	PRINT ''
END

IF (@SyncTableUpdated > 0)
BEGIN
	PRINT '** ' + CONVERT(NVARCHAR(25), @SyncTableUpdated) + ' EXISTING RECORDS UPDATED IN [sync].[tblSyncTable] **'
	PRINT ''
	SELECT * FROM @tblSyncTableRefData WHERE ActionType IN ( 'UPDATE' );
END

SET NOCOUNT OFF
